window.VF1_UNITS = {"8":{"unit":8,"code":"VF1-U08","title":"People & Daily Life","startNumber":177,"endNumber":211,"entries":[{"number":177,"term":"admit to doing st","sourceTerm":"admit (v) to doing st","spoken":"admit to doing something","ipa":"/əˈdmɪt tuː ˈduːɪŋ ˈsʌmθɪŋ/","type":"verb","meaning":"thừa nhận đã làm gì","definition":"To accept that you did something.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: admit (v) to doing st","example":"The student admitted taking the phone and returned it."},{"number":178,"term":"arrest sb for doing st","sourceTerm":"arrest (v) sb for doing st","spoken":"arrest somebody for doing something","ipa":"/ɚˈɛst ˈsʌˌmbɑːdi fɔːr ˈduːɪŋ ˈsʌmθɪŋ/","type":"verb","meaning":"bắt giữ ai đó vì đã làm gì","definition":"To take someone into police control for an offence.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: arrest (v) sb for doing st","example":"Police arrested the driver for leaving the scene."},{"number":179,"term":"accuse sb of doing st","sourceTerm":"accuse (v) sb of doing st","spoken":"accuse somebody of doing something","ipa":"/əˈkjuːz ˈsʌˌmbɑːdi ʌv ˈduːɪŋ ˈsʌmθɪŋ/","type":"verb","meaning":"buộc tội ai đó vì đã làm gì","definition":"To say that someone did something wrong or illegal.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: accuse (v) sb of doing st","example":"The teacher did not accuse anyone of cheating without clear evidence."},{"number":180,"term":"blame sb for doing st · blame st on sb · put the blame on sb/st","sourceTerm":"blame (v) sb for doing st · blame (v) st on sb · put the blame on sb/st","spoken":"blame somebody for doing something · blame something on somebody · put the blame on somebody or something","ipa":"/bleɪm ˈsʌˌmbɑːdi fɔːr ˈduːɪŋ ˈsʌmθɪŋ bleɪm ˈsʌmθɪŋ ɑːn ˈsʌˌmbɑːdi pʊt ðə bleɪm ɑːn ˈsʌˌmbɑːdi ɔːr ˈsʌmθɪŋ/","type":"verb","meaning":"đổ lỗi cho ai vì làm gì · quy lỗi một việc cho ai · đổ trách nhiệm cho ai/điều gì","definition":"To say that someone is responsible for something bad.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: blame (v) sb for doing st · blame (v) st on sb · put the blame on sb/st","example":"Do not blame Lan for the mistake or blame the problem on one person; do not put all the blame on her."},{"number":181,"term":"criticize sb for doing st · critical · criticism","sourceTerm":"criticize (v) sb for doing st · critical (a) · criticism (n)","spoken":"criticize somebody for doing something · critical · criticism","ipa":"/ˈkrɪtɪˌsaɪz ˈsʌˌmbɑːdi fɔːr ˈduːɪŋ ˈsʌmθɪŋ ˈkrɪtɪkəl ˈkrɪtɪˌsɪzəm/","type":"verb · noun · adjective","meaning":"chỉ trích ai vì làm gì · mang tính phê bình/chỉ trích · sự/lời chỉ trích","definition":"To express disapproval; expressing careful judgement; an unfavourable comment.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: criticize (v) sb for doing st · critical (a) · criticism (n)","example":"The teacher criticized the report for missing facts; her critical comments and criticism were fair."},{"number":182,"term":"punish sb for doing st ~ penalize sb · punishment ~ penalty","sourceTerm":"punish (v) sb for doing st ~ penalize (v) sb · punishment (n) ~ penalty (n)","spoken":"punish somebody for doing something ~ penalize somebody · punishment ~ penalty","ipa":"/ˈpʌnɪʃ ˈsʌˌmbɑːdi fɔːr ˈduːɪŋ ˈsʌmθɪŋ ˈpɛnəˌlaɪz ˈsʌˌmbɑːdi ˈpʌnɪʃmənt ˈpɛnəlti/","type":"verb · noun","meaning":"phạt ai vì làm gì ~ áp dụng hình phạt chính thức với ai · hình phạt","definition":"To give a penalty for wrongdoing; a penalty.","note":"punish là phạt người vì hành vi; penalize thường là áp dụng hình phạt chính thức. punishment và penalty đều là danh từ.","example":"The school punished and penalized the player for cheating; the punishment was a one-game penalty."},{"number":183,"term":"forgive sb for st · forgiveness","sourceTerm":"forgive (v) sb for st · forgiveness (n)","spoken":"forgive somebody for something · forgiveness","ipa":"/fɚˈɡɪv ˈsʌˌmbɑːdi fɔːr ˈsʌmθɪŋ fɚˈɡɪvnəs/","type":"verb · noun","meaning":"tha thứ cho ai về điều gì · sự tha thứ","definition":"To stop feeling angry with someone; the act of forgiving.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: forgive (v) sb for st · forgiveness (n)","example":"Mai forgave her friend for the mistake, and her forgiveness helped them become friends again."},{"number":184,"term":"charity","sourceTerm":"charity (n)","spoken":"charity","ipa":"/ˈtʃɛrɪti/","type":"noun","meaning":"tổ chức từ thiện · hoạt động/lòng từ thiện","definition":"An organization that helps people in need; the activity of giving help or money.","note":"charity có thể chỉ một tổ chức từ thiện hoặc hoạt động giúp đỡ người khó khăn.","example":"Our class collected books for a local charity that supports children in need."},{"number":185,"term":"commit a crime","sourceTerm":"commit (v) a crime","spoken":"commit a crime","ipa":"/kəˈmɪt ə kraɪm/","type":"verb","meaning":"phạm tội","definition":"To carry out a crime.","note":"","example":"A person who commits a crime may have to go to court."},{"number":186,"term":"court","sourceTerm":"court (n)","spoken":"court","ipa":"/kɔːrt/","type":"noun","meaning":"tòa án","definition":"A place where legal cases are decided.","note":"","example":"The case was discussed in court."},{"number":187,"term":"crime · criminal","sourceTerm":"crime (n) · criminal (n)","spoken":"crime · criminal","ipa":"/kraɪm ˈkrɪmənəl/","type":"noun","meaning":"tội phạm/hành vi phạm tội · người phạm tội","definition":"An illegal act; a person who commits one.","note":"","example":"The police are studying the crime and looking for the criminal."},{"number":188,"term":"community","sourceTerm":"community (n)","spoken":"community","ipa":"/kəˈmjuːnəti/","type":"noun","meaning":"cộng đồng","definition":"People living in the same area or sharing an interest.","note":"","example":"The school and the local community cleaned the park together."},{"number":189,"term":"familiar with sb/st","sourceTerm":"familiar (a) with sb/st","spoken":"familiar with somebody or something","ipa":"/fəˈmɪljɚ wɪð ˈsʌˌmbɑːdi ɔːr ˈsʌmθɪŋ/","type":"adjective","meaning":"quen thuộc với ai/cái gì","definition":"Well known to someone through experience.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: familiar (a) with sb/st","example":"Students should become familiar with the rules before the activity."},{"number":190,"term":"(il)legal","sourceTerm":"(il)legal (a)","spoken":"illegal","ipa":"/ˌɪˈliːɡəl/","type":"adjective","meaning":"(bất) hợp pháp","definition":"Allowed or not allowed by law.","note":"","example":"The action was illegal because it was not legal under local rules."},{"number":191,"term":"politics · political · politician","sourceTerm":"politics (n) · political (a) · politician (n)","spoken":"politics · political · politician","ipa":"/ˈpɑːləˌtɪks pəˈlɪtəkəl ˌpɑːləˈtɪʃən/","type":"noun · adjective","meaning":"chính trị · thuộc chính trị · chính trị gia","definition":"Activities connected with government; relating to government; a person in politics.","note":"","example":"The politician discussed a political issue during a lesson on politics."},{"number":192,"term":"prison · imprison · imprisonment · prisoner","sourceTerm":"prison (n) · imprison (v) · imprisonment (n) · prisoner (n)","spoken":"prison · imprison · imprisonment · prisoner","ipa":"/ˈprɪzən ˌɪˈmprɪzən ˌɪˈmprɪzənmənt ˈprɪzənɚ/","type":"verb · noun","meaning":"nhà tù · bỏ tù · sự giam cầm · tù nhân","definition":"A place where offenders are held; to put in prison; a person held there.","note":"","example":"The court imprisoned the criminal; during his imprisonment, the prisoner studied in prison."},{"number":193,"term":"protest","sourceTerm":"protest (v,n)","spoken":"protest","ipa":"/ˈproʊˌtɛst/","type":"verb · noun","meaning":"biểu tình, phản đối","definition":"To publicly object; a public expression of disagreement.","note":"","example":"Residents held a peaceful protest against the new road."},{"number":194,"term":"reside · resident ~ inhabitant","sourceTerm":"reside (v) · resident (n) ~ inhabitant (n)","spoken":"reside · resident ~ inhabitant","ipa":"/rɪˈzaɪd ˈrɛzɪdənt ɪˈnhæbətənt/","type":"verb · noun","meaning":"cư trú/sinh sống · cư dân/người sinh sống","definition":"To live in a place; a person who lives there.","note":"resident là người cư trú; inhabitant là người hoặc sinh vật sống trong một khu vực; reside là động từ trang trọng.","example":"Many residents and other inhabitants reside in this area."},{"number":195,"term":"responsible for st · responsibility","sourceTerm":"responsible (a) for st · responsibility (n)","spoken":"responsible for something · responsibility","ipa":"/riˈspɑːnsəbəl fɔːr ˈsʌmθɪŋ riˌspɑːnsəˈbɪləti/","type":"noun · adjective","meaning":"chịu trách nhiệm về điều gì · trách nhiệm/nghĩa vụ","definition":"Having a duty for something; a duty to deal with something.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: responsible (a) for st · responsibility (n)","example":"The council is responsible for road safety and accepts this responsibility."},{"number":196,"term":"rob · robbery","sourceTerm":"rob (v) · robbery (n)","spoken":"rob · robbery","ipa":"/rɑːb ˈrɑːbɚi/","type":"verb · noun","meaning":"cướp · vụ cướp","definition":"To steal from a person or place; the crime of stealing.","note":"","example":"A thief robbed the shop, and a camera recorded the robbery."},{"number":197,"term":"social · socialize · society · sociable","sourceTerm":"social (a) · socialize (v) · society (n) · sociable (a)","spoken":"social · socialize · society · sociable","ipa":"/ˈsoʊʃəl ˈsoʊʃəˌlaɪz səˈsaɪəti ˈsoʊʃəbəl/","type":"verb · noun · adjective","meaning":"thuộc xã hội · giao lưu/giao thiệp · xã hội · hòa đồng","definition":"Connected with society; to meet people socially; a community; friendly and sociable.","note":"","example":"Social clubs help students socialize, meet others in society, and become more sociable."},{"number":198,"term":"type · typical","sourceTerm":"type (n) · typical (a)","spoken":"type · typical","ipa":"/taɪp ˈtɪpəkəl/","type":"noun · adjective","meaning":"loại, kiểu · điển hình, đặc trưng","definition":"A category; showing the usual features of a category.","note":"","example":"This type of traffic problem is typical of large cities."},{"number":199,"term":"against the law","sourceTerm":"against the law","spoken":"against the law","ipa":"/əˈɡɛnst ðə lɔː/","type":"phrase / pattern","meaning":"phạm luật","definition":"Not permitted by law.","note":"","example":"Driving without a licence is against the law."},{"number":200,"term":"courage · discourage sb from doing st >< encourage sb to do st","sourceTerm":"courage (n) · discourage (v) sb from doing st >< encourage (v) sb to do st","spoken":"courage · discourage somebody from doing something >< encourage somebody to do something","ipa":"/ˈkɝːədʒ dɪˈskɝːɪdʒ ˈsʌˌmbɑːdi frʌm ˈduːɪŋ ˈsʌmθɪŋ ɛˈnkɝːɪdʒ ˈsʌˌmbɑːdi tuː duː ˈsʌmθɪŋ/","type":"verb · noun","meaning":"lòng can đảm · ngăn/nản ai làm gì >< khuyến khích ai làm gì","definition":"Bravery; to reduce confidence; to give support and confidence.","note":"Chú ý cặp đối lập hoặc điểm khác nhau được đánh dấu trong danh sách. Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: courage (n) · discourage (v) sb from doing st >< encourage (v) sb to do st","example":"Lan showed courage and encouraged her friends to continue; she did not let fear discourage them from trying."},{"number":201,"term":"equal >< unequal · equality >< inequality","sourceTerm":"equal (a) >< unequal (a) · equality (n) >< inequality (n)","spoken":"equal >< unequal · equality >< inequality","ipa":"/ˈiːkwəl əˈniːkwəl ɪˈkwɑːləti ˌɪnɪˈkwɑːləti/","type":"noun · adjective","meaning":"bình đẳng/ngang bằng >< không bình đẳng · sự bình đẳng >< sự bất bình đẳng","definition":"Having the same rights; fairness; unfair differences.","note":"Chú ý cặp đối lập hoặc điểm khác nhau được đánh dấu trong danh sách. Cách kết hợp: equal (a) >< unequal (a) · equality (n) >< inequality (n)","example":"Equal access to school supports equality, while unequal access increases inequality."},{"number":202,"term":"guilty of st >< innocent of st","sourceTerm":"guilty (a) of st >< innocent (a) of st","spoken":"guilty of something >< innocent of something","ipa":"/ˈɡɪlti ʌv ˈsʌmθɪŋ ˈɪnəsənt ʌv ˈsʌmθɪŋ/","type":"adjective","meaning":"có tội/có lỗi về điều gì >< vô tội/không có lỗi","definition":"Responsible for a crime; not responsible for a crime.","note":"guilty of nghĩa là có tội/có lỗi về; innocent of nghĩa là vô tội/không có lỗi về.","example":"The court found one man guilty of the crime and proved another man innocent."},{"number":203,"term":"government","sourceTerm":"government (n)","spoken":"government","ipa":"/ˈɡʌvɚmənt/","type":"noun","meaning":"chính phủ","definition":"The group that controls and administers a country.","note":"","example":"The government opened a new library for the town."},{"number":204,"term":"population","sourceTerm":"population (n)","spoken":"population","ipa":"/ˌpɑːpjəˈleɪʃən/","type":"noun","meaning":"dân số","definition":"The number of people living in a place.","note":"","example":"The city's population has grown quickly in the last ten years."},{"number":205,"term":"respond · response · in response to","sourceTerm":"respond (v) · response (n) · in response to","spoken":"respond · response · in response to","ipa":"/rɪˈspɑːnd rɪˈspɑːns ɪn rɪˈspɑːns tuː/","type":"verb · noun","meaning":"phản hồi/đáp lại · lời/sự phản hồi · để đáp lại điều gì","definition":"To reply or react; an answer or reaction; as a reply to something.","note":"respond là động từ; response là danh từ; in response to + sự việc/ý kiến.","example":"The school responded quickly; in response to parents' concerns, it sent a clear written response."},{"number":206,"term":"break into","sourceTerm":"break into","spoken":"break into","ipa":"/breɪk ˈɪntu/","type":"phrasal verb","meaning":"đột nhập vào…","definition":"To enter a building illegally by force.","note":"","example":"Someone broke into the office and took two computers."},{"number":207,"term":"catch up with sb/st","sourceTerm":"catch up with sb/st","spoken":"catch up with somebody or something","ipa":"/kætʃ ʌp wɪð ˈsʌˌmbɑːdi ɔːr ˈsʌmθɪŋ/","type":"phrasal verb","meaning":"bắt kịp với ai/cái gì","definition":"To reach the same level or position.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: catch up with sb/st","example":"Mai studied after class to catch up with the group."},{"number":208,"term":"put st away","sourceTerm":"put st away","spoken":"put something away","ipa":"/pʊt ˈsʌmθɪŋ əˈweɪ/","type":"phrasal verb","meaning":"cất cái gì đi; cất vào đúng chỗ","definition":"To return something to the place where it is normally kept.","note":"Dùng đúng cấu trúc kết hợp của từ; sb là viết tắt của somebody, st là viết tắt của something. Cách kết hợp: put st away","example":"Please put the books away on the shelf after the lesson."},{"number":209,"term":"get away with","sourceTerm":"get away with","spoken":"get away with","ipa":"/ɡɛt əˈweɪ wɪð/","type":"phrasal verb","meaning":"thoát tội","definition":"To avoid punishment for doing something wrong.","note":"","example":"People should not get away with breaking safety rules."},{"number":210,"term":"wash up ~ do the washing up","sourceTerm":"wash up ~ do the washing up","spoken":"wash up ~ do the washing up","ipa":"/wɑːʃ ʌp duː ðə ˈwɑːʃɪŋ ʌp/","type":"phrasal verb","meaning":"rửa bát","definition":"To wash plates, cups, and cooking equipment.","note":"wash up và do the washing up đều chỉ việc rửa bát; trong Anh–Mỹ còn thường nói do the dishes.","example":"We washed up after lunch and finished doing the washing up together."},{"number":211,"term":"keep/stay in touch with sb ~ be in contact with sb","sourceTerm":"keep/stay (v) in touch with sb ~ be (v) in contact with sb","spoken":"keep or stay in touch with somebody ~ be in contact with somebody","ipa":"/kiːp ɔːr steɪ ɪn tʌtʃ wɪð ˈsʌˌmbɑːdi biː ɪn ˈkɑːˌntækt wɪð ˈsʌˌmbɑːdi/","type":"verb","meaning":"liên hệ, liên lạc với ai","definition":"Communicating regularly with someone.","note":"keep/stay in touch thường gợi duy trì quan hệ; be in contact with trung tính và trang trọng hơn.","example":"The school stays in touch with parents and keeps in contact with them by email."}],"pronunciationFocus":[{"entryNumber":178,"points":[{"category":"final-sound","note":"arrest kết thúc bằng cụm /st/; không bỏ /t/"}]},{"entryNumber":179,"points":[{"category":"final-sound","note":"accuse kết thúc bằng /z/, không phải /s/"}]},{"entryNumber":181,"points":[{"category":"word-stress","note":"criticize, critical và criticism đều giữ trọng âm chính ở âm đầu /ˈkrɪ/"}]},{"entryNumber":185,"points":[{"category":"final-sound","note":"commit kết thúc bằng /t/"},{"category":"linking","note":"Trong commit‿a crime, nối /t/ cuối commit sang âm /ə/ của a"}]},{"entryNumber":191,"points":[{"category":"word-stress","note":"politics nhấn âm đầu; political nhấn âm hai; politician nhấn vào /ˈtɪʃ/"}]},{"entryNumber":192,"points":[{"category":"common-error","note":"prison và prisoner có âm /z/, không đọc chữ s thành /s/"},{"category":"word-stress","note":"prison và prisoner nhấn âm đầu; imprison nhấn âm hai"}]},{"entryNumber":195,"points":[{"category":"word-stress","note":"responsible nhấn vào /ˈspɑːn/; responsibility chuyển trọng âm sang /ˈbɪl/"}]},{"entryNumber":206,"points":[{"category":"linking","note":"Trong break‿into, nối /k/ cuối break sang nguyên âm /ɪ/ của into"}]}]}};
